import React, { useState } from 'react';
import '../styles/SubscribeSection.css';

const SubscribeSection = () => {
    const [phone, setPhone] = useState('');
    const [email, setEmail] = useState('');
    const [privacyAccepted, setPrivacyAccepted] = useState(false);
    const [error, setError] = useState('');

    const handleSubmit = (e) => {
        e.preventDefault();
        
        // Валидация полей
        if (!phone.trim() || !email.trim()) {
            setError('Будь ласка, заповніть всі поля');
            return;
        }
        
        if (!privacyAccepted) {
            setError('Будь ласка, прийміть політику конфіденційності');
            return;
        }
        
        // Простая валидация email
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(email)) {
            setError('Будь ласка, введіть коректну електронну пошту');
            return;
        }
        
        // Если все проверки пройдены
        setError('');
        alert('Дякуємо за підписку! Ви отримали знижку 5% на покупки.');
        
        // Очистка формы
        setPhone('');
        setEmail('');
        setPrivacyAccepted(false);
    };

    return (
        <section className="subscribe-section">
            <h2 className="subscribe-title">Підпишіться на розсилку</h2>
            <p className="subscribe-description">Підпишіться на нашу розсилку та отримайте знижку 5% на покупки в нашому магазині!</p>
            
            <form className="subscribe-form" onSubmit={handleSubmit}>
                <input
                    type="tel"
                    placeholder="Номер телефону"
                    value={phone}
                    onChange={(e) => setPhone(e.target.value)}
                />
                <input
                    type="email"
                    placeholder="Електронна пошта"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                />
                <button type="submit">Підписатись</button>
            </form>
            
            <div className="subscribe-checkbox">
                <input
                    type="checkbox"
                    id="privacy"
                    checked={privacyAccepted}
                    onChange={(e) => setPrivacyAccepted(e.target.checked)}
                />
                <label htmlFor="privacy">Я приймаю <a href="#">Політика конфіденційності</a></label>
            </div>
            
            {error && <div className="error-message">{error}</div>}
        </section>
    );
};

export default SubscribeSection;
